## Hub 核心概念

**Hub** 是 SignalR 的核心，它是一个高级管道，允许客户端和服务器互相调用方法：
```csharp
public class ChatHub : Hub
{
    public async Task SendMessage(string user, string message)
    {
        // 调用所有客户端的 ReceiveMessage 方法
        await Clients.All.SendAsync("ReceiveMessage", user, message);
    }

    public async Task SendToGroup(string groupName, string message)
    {
        // 调用特定组的客户端
        await Clients.Group(groupName).SendAsync("ReceiveMessage", message);
    }

    // 连接生命周期
    public override async Task OnConnectedAsync()
    {
        await Groups.AddToGroupAsync(Context.ConnectionId, "ChatRoom");
        await base.OnConnectedAsync();
    }

    public override async Task OnDisconnectedAsync(Exception exception)
    {
        await Groups.RemoveFromGroupAsync(Context.ConnectionId, "ChatRoom");
        await base.OnDisconnectedAsync(exception);
    }
}
```


## 客户端调用

**JavaScript 客户端**：
```javascript
const connection = new signalR.HubConnectionBuilder()
    .withUrl("/chatHub")
    .build();

// 监听服务器方法
connection.on("ReceiveMessage", (user, message) => {
    console.log(`${user}: ${message}`);
});

// 调用服务器方法
await connection.start();
await connection.invoke("SendMessage", "User1", "Hello!");
```

**.NET 客户端**：
```csharp
var connection = new HubConnectionBuilder()
    .WithUrl("https://localhost:5001/chatHub")
    .Build();

connection.On<string, string>("ReceiveMessage", (user, message) =>
{
    Console.WriteLine($"{user}: {message}");
});

await connection.StartAsync();
await connection.InvokeAsync("SendMessage", "User1", "Hello!");
```


## 客户端方法调用

**调用所有客户端**：
```csharp
await Clients.All.SendAsync("MethodName", arg1, arg2);
```

**调用特定客户端**：
```csharp
await Clients.Caller.SendAsync("MethodName");
await Clients.Client(connectionId).SendAsync("MethodName");
```

**调用特定组**：
```csharp
await Clients.Group("groupName").SendAsync("MethodName");
await Clients.OthersInGroup("groupName").SendAsync("MethodName");
```

**调用特定用户**：
```csharp
await Clients.User(userId).SendAsync("MethodName");
```

## 连接管理

**连接 ID**：每个连接都有唯一标识
```csharp
string connectionId = Context.ConnectionId;
```

**分组管理**：
```csharp
await Groups.AddToGroupAsync(connectionId, "groupName");
await Groups.RemoveFromGroupAsync(connectionId, "groupName");
```

**用户标识**：
```csharp
string userId = Context.UserIdentifier;
```


## 强类型 Hub

使用接口定义客户端方法：
```csharp
public interface IChatClient
{
    Task ReceiveMessage(string user, string message);
    Task UserConnected(string userId);
    Task UserDisconnected(string userId);
}

public class ChatHub : Hub<IChatClient>
{
    public async Task SendMessage(string message)
    {
        await Clients.All.ReceiveMessage(Context.UserIdentifier, message);
    }
}
```


## 身份验证和授权

```csharp
[Authorize]
public class SecureHub : Hub
{
    [Authorize(Roles = "Admin")]
    public async Task AdminOnlyMethod()
    {
        // 只有管理员可以调用
    }
}
```


## 错误处理

```csharp
public class ChatHub : Hub
{
    public async Task SendMessage(string message)
    {
        try
        {
            await Clients.All.ReceiveMessage(message);
        }
        catch (Exception ex)
        {
            // 通知调用者错误
            await Clients.Caller.SendAsync("Error", ex.Message);
        }
    }
}
```


## 性能优化

1. **使用强类型 Hub**：编译时检查
2. **减少消息大小**：只发送必要数据
3. **使用分组**：避免广播给所有用户
4. **配置传输方式**：优先使用 WebSocket
5. **启用消息压缩**：减少带宽


## 与 WebSocket 对比

**SignalR 优点**：
- 简单易用的 API
- 自动选择传输方式
- 内置重连机制
- 支持远程方法调用

**原生 WebSocket 优点**：
- 更底层，更灵活
- 更好的性能
- 更小的开销

**选择建议**：
- 需要快速开发：SignalR
- 需要极致性能：原生 WebSocket
- 需要兼容性：SignalR（自动降级）

using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.SignalR;
using Microsoft.Extensions.Logging;

namespace SignalRDemo
{
    // 强类型接口
    public interface IChatClient
    {
        Task ReceiveMessage(string user, string message, DateTime timestamp);
        Task UserConnected(string userId, string username);
        Task UserDisconnected(string userId);
        Task ReceiveNotification(string message);
    }

    // 聊天 Hub
    [Authorize]
    public class ChatHub : Hub<IChatClient>
    {
        private static readonly ConcurrentDictionary<string, string> Users = new();
        private readonly ILogger<ChatHub> _logger;

        public ChatHub(ILogger<ChatHub> logger)
        {
            _logger = logger;
        }

        public async Task SendMessage(string message)
        {
            var userId = Context.UserIdentifier;
            var username = Users.GetValueOrDefault(userId, "Unknown");

            _logger.LogInformation($"{username} 发送消息: {message}");

            await Clients.All.ReceiveMessage(username, message, DateTime.UtcNow);
        }

        public async Task SendToUser(string targetUserId, string message)
        {
            var senderId = Context.UserIdentifier;
            var senderName = Users.GetValueOrDefault(senderId, "Unknown");

            await Clients.User(targetUserId).ReceiveMessage(senderName, message, DateTime.UtcNow);
        }

        public async Task JoinGroup(string groupName)
        {
            await Groups.AddToGroupAsync(Context.ConnectionId, groupName);
            await Clients.Group(groupName).ReceiveNotification(
                $"{Users.GetValueOrDefault(Context.UserIdentifier, "Unknown")} 加入了群组");
        }

        public async Task LeaveGroup(string groupName)
        {
            await Groups.RemoveFromGroupAsync(Context.ConnectionId, groupName);
            await Clients.Group(groupName).ReceiveNotification(
                $"{Users.GetValueOrDefault(Context.UserIdentifier, "Unknown")} 离开了群组");
        }

        public async Task SendToGroup(string groupName, string message)
        {
            var username = Users.GetValueOrDefault(Context.UserIdentifier, "Unknown");
            await Clients.Group(groupName).ReceiveMessage(username, message, DateTime.UtcNow);
        }

        public override async Task OnConnectedAsync()
        {
            var userId = Context.UserIdentifier;
            var username = Context.User?.Identity?.Name ?? userId;

            Users[userId] = username;

            _logger.LogInformation($"用户 {username} 连接，ConnectionId: {Context.ConnectionId}");

            await Clients.All.UserConnected(userId, username);
            await Clients.Caller.ReceiveNotification("欢迎加入聊天室！");

            await base.OnConnectedAsync();
        }

        public override async Task OnDisconnectedAsync(Exception exception)
        {
            var userId = Context.UserIdentifier;
            var username = Users.GetValueOrDefault(userId, "Unknown");

            Users.TryRemove(userId, out _);

            _logger.LogInformation($"用户 {username} 断开连接");

            await Clients.All.UserDisconnected(userId);

            await base.OnDisconnectedAsync(exception);
        }
    }

    // 通知 Hub
    public class NotificationHub : Hub
    {
        public async Task SendNotification(string userId, string message)
        {
            await Clients.User(userId).SendAsync("ReceiveNotification", message);
        }

        public async Task BroadcastNotification(string message)
        {
            await Clients.All.SendAsync("ReceiveNotification", message);
        }
    }

    // 进度报告 Hub
    public class ProgressHub : Hub
    {
        public async Task StartLongRunningTask(string taskId)
        {
            // 模拟长时间运行的任务
            for (int i = 0; i <= 100; i += 10)
            {
                await Task.Delay(500);
                await Clients.Caller.SendAsync("ProgressUpdate", taskId, i);
            }

            await Clients.Caller.SendAsync("TaskCompleted", taskId);
        }
    }

    // 配置服务
    public static class SignalRServiceCollectionExtensions
    {
        public static IServiceCollection AddCustomSignalR(this IServiceCollection services)
        {
            services.AddSignalR(options =>
            {
                options.EnableDetailedErrors = true;
                options.KeepAliveInterval = TimeSpan.FromSeconds(15);
                options.ClientTimeoutInterval = TimeSpan.FromSeconds(30);
                options.MaximumReceiveMessageSize = 1024 * 1024; // 1MB
            })
            .AddJsonProtocol(options =>
            {
                options.PayloadSerializerOptions.PropertyNamingPolicy =
                    System.Text.Json.JsonNamingPolicy.CamelCase;
            });

            return services;
        }
    }

    // 配置中间件
    public static class SignalREndpointRouteBuilderExtensions
    {
        public static IEndpointRouteBuilder MapCustomHubs(this IEndpointRouteBuilder endpoints)
        {
            endpoints.MapHub<ChatHub>("/hubs/chat");
            endpoints.MapHub<NotificationHub>("/hubs/notification");
            endpoints.MapHub<ProgressHub>("/hubs/progress");

            return endpoints;
        }
    }

